def solution(s):
    s_list = list(s)

    # Handle hours - first digit (index 0)
    if s_list[0] == '?':
        # If second digit is '?' or between '0'-'1', we can use '1' for first digit
        # Otherwise, if second digit is '2'-'9', we must use '0'
        if s_list[1] == '?' or s_list[1] <= '1':
            s_list[0] = '1'
        else:
            s_list[0] = '0'

    # Handle hours - second digit (index 1)
    if s_list[1] == '?':
        # If first digit is '1', second digit can be at most '1' (for 11)
        # If first digit is '0', second digit can be at most '9' (for 09)
        if s_list[0] == '1':
            s_list[1] = '1'
        else:
            s_list[1] = '9'

    # Handle minutes - first digit (index 3)
    if s_list[3] == '?':
        # First digit of minutes can be at most '5'
        s_list[3] = '5'

    # Handle minutes - second digit (index 4)
    if s_list[4] == '?':
        # Second digit of minutes can be at most '9'
        s_list[4] = '9'

