import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    grid = [list(next(it).strip()) for _ in range(H)]

    # is_free[i][j] == True  ⇔  cell (i,j) is '.' and has no magnet neighbour
    is_free = [[False] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.':
                has_magnet = False
                for di, dj in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                    ni, nj = i + di, j + dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                        has_magnet = True
                        break
                if not has_magnet:
                    is_free[i][j] = True

    visited_free = [[False] * W for _ in range(H)]
    max_deg = 0

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '.' and is_free[i][j] and not visited_free[i][j]:
                q = deque()
                q.append((i, j))
                visited_free[i][j] = True
                free_cnt = 0
                blocked = set()          # blocked cells reachable from this component

                while q:
                    x, y = q.popleft()
                    free_cnt += 1
                    # only free cells can move, but we only push free cells
                    for dx, dy in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == '.':
                            if is_free[nx][ny]:
                                if not visited_free[nx][ny]:
                                    visited_free[nx][ny] = True
                                    q.append((nx, ny))
                            else:
                                blocked.add((nx, ny))

                region = free_cnt + len(blocked)
                if region > max_deg:
                    max_deg = region

    # If there is no free cell at all, every non‑magnet cell has degree 1.
    if max_deg < 1:
        max_deg = 1

    print(max_deg)


if __name__ == "__main__":
    solve()

