from itertools import permutations, product

def parse_polyomino(lines):
    grid = [list(line.strip()) for line in lines]
    coords = [(r, c) for r in range(4) for c in range(4) if grid[r][c] == '#']
    min_r = min(r for r, c in coords)
    min_c = min(c for r, c in coords)
    normalized = sorted((r - min_r, c - min_c) for r, c in coords)
    return tuple(normalized)

def rotate(poly):
    return tuple(sorted((c, -r) for r, c in poly))

def normalize(poly):
    min_r = min(r for r, c in poly)
    min_c = min(c for r, c in poly)
    return tuple(sorted((r - min_r, c - min_c) for r, c in poly))

def translate_to(poly, dr, dc):
    return tuple((r + dr, c + dc) for r, c in poly)

def fits_in_grid(poly):
    return all(0 <= r < 4 and 0 <= c < 4 for r, c in poly)

def place_poly(grid, poly):
    for r, c in poly:
        if grid[r][c] != 0:
            return False
    for r, c in poly:
        grid[r][c] = 1
    return True

def remove_poly(grid, poly):
    for r, c in poly:
        grid[r][c] = 0

def solve():
