def countRightTriangles(grid):
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Count ones in each row and column
    row_counts = [0] * rows
    col_counts = [0] * cols

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                row_counts[i] += 1
                col_counts[j] += 1

    count = 0

    # For each cell that contains 1, count how many right triangles can be formed
    # with this cell as the right angle vertex
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                # If this cell is the right angle, we need one other 1 in the same row
                # and one other 1 in the same column
                if row_counts[i] > 1 and col_counts[j] > 1:
                    # Number of ways to choose one other 1 from the same row (excluding current)
                    # and one other 1 from the same column (excluding current)
                    count += (row_counts[i] - 1) * (col_counts[j] - 1)

    return count
