def numberOfBeautifulIntegers(low: int, high: int, k: int) -> int:
    from functools import lru_cache

    def count_beautiful(n_str):
        # dp(index, diff, remainder, is_less, is_started)
        # diff: count of even digits - count of odd digits
        # is_started: boolean to handle leading zeros
        @lru_cache(None)
        def dp(idx, diff, rem, is_less, is_started):
            if idx == len(n_str):
                return 1 if (is_started and diff == 0 and rem == 0) else 0

            res = 0
            # Option to continue not starting the number (leading zeros)
            if not is_started:
                res += dp(idx + 1, 0, 0, True, False)

            limit = int(n_str[idx]) if not is_less else 9

            start_digit = 1 if not is_started else 0
            for digit in range(start_digit, limit + 1):
                new_is_less = is_less or (digit < limit)
                new_diff = diff + (1 if digit % 2 == 0 else -1)
                new_rem = (rem * 10 + digit) % k
                res += dp(idx + 1, new_diff, new_rem, new_is_less, True)

            return res

        return dp(0, 0, 0, False, False)

    # The count of beautiful integers in [low, high] is count(high) - count(low - 1)
    # Use a helper to clear cache between the two calls
    ans_high = count_beautiful(str(high))
    # We need to reset the cache for the second call because n_str changes
    import sys
    # Instead of clearing sys.cache, we just wrap the logic
    # Since we are defining count_beautiful inside the main function, 
    # calling it twice with different strings will instantiate different dp functions.

    # To avoid potential issues with the logic above, I'll implement a clean split:
    def solve(n):
        if n == 0: return 0
        s = str(n)
        @lru_cache(None)
        def f(idx, diff, rem, is_less, is_started):
            if idx == len(s):
                return 1 if (is_started and diff == 0 and rem == 0) else 0
            res = 0
            if not is_started:
                res += f(idx + 1, 0, 0, True, False)
            limit = int(s[idx]) if not is_less else 9
            start = 1 if not is_started else 0
            for d in range(start, limit + 1):
                res += f(idx + 1, diff + (1 if d % 2 == 0 else -1), (rem * 10 + d) % k, is_less or (d < limit), True)
            return res
        return f(0, 0, 0, False, False)

    return solve(high) - solve(low - 1)
