import sys

def solve():
    # Read H and W
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    H = int(input_data[0])
    W = int(input_data[1])
    grid = [list(row) for row in input_data[2:]]

    # exists[i][j] tracks if the cookie at (i, j) is still there
    exists = [[True] * W for _ in range(H)]

    # Track current counts and unique characters per row and column
    # row_counts[i] = {char: count}
    row_counts = []
    for i in range(H):
        counts = {}
        for j in range(W):
            char = grid[i][j]
            counts[char] = counts.get(char, 0) + 1
        row_counts.append(counts)

    col_counts = []
    for j in range(W):
        counts = {}
        for i in range(H):
            char = grid[i][j]
            counts[char] = counts.get(char, 0) + 1
        col_counts.append(counts)

    # Queues to check rows and columns that might have changed
    # Use a set to avoid duplicate checks in one iteration
    rows_to_check = set(range(H))
    cols_to_check = set(range(W))

    while True:
        to_remove = []

        # Check rows
        current_rows = list(rows_to_check)
        rows_to_check = set()
        for i in current_rows:
            # A row can be removed if:
            # 1. There are at least 2 cookies remaining.
            # 2. All remaining cookies have the same color.
            remaining_count = sum(row_counts[i].values())
            if remaining_count >= 2:
                if len(row_counts[i]) == 1:
                    # All remaining are the same color
                    for j in range(W):
                        if exists[i][j]:
                            to_remove.append((i, j))

        # Check columns
        current_cols = list(cols_to_check)
        cols_to_check = set()
        for j in current_cols:
            remaining_count = sum(col_counts[j].values())
            if remaining_count >= 2:
                if len(col_counts[j]) == 1:
                    for i in range(H):
                        if exists[i][j]:
                            to_remove.append((i, j))

        if not to_remove:
            break

        # Remove cookies and update counters
        # Use a set because a cookie might be marked by both row and col
        unique_removals = set(to_remove)
        for i, j in unique_removals:
            if exists[i][j]:
                char = grid[i][j]
                exists[i][j] = False

                # Update row counters
                row_counts[i][char] -= 1
                if row_counts[i][char] == 0:
                    del row_counts[i][char]

                # Update col counters
                col_counts[j][char] -= 1
