def solve(s: str, k: int) -> int:
    n = len(s)

    def get_cost(sub):
        m = len(sub)
        if m < 2:
            return float('inf')

        min_changes = float('inf')
        # Check all possible divisors d such that 1 <= d < m
        for d in range(1, m):
            if m % d == 0:
                current_changes = 0
                # For each group formed by modulo d
                for i in range(d):
                    # The group is sub[i], sub[i+d], sub[i+2d]...
                    group = [sub[j] for j in range(i, m, d)]
                    # To make this group a palindrome, we count changes
                    l, r = 0, len(group) - 1
                    while l < r:
                        if group[l] != group[r]:
                            current_changes += 1
                        l += 1
                        r -= 1
                min_changes = min(min_changes, current_changes)
        return min_changes

    # Precompute the cost to make any substring s[i:j] a semi-palindrome
    cost = [[float('inf')] * (n + 1) for _ in range(n)]
    for i in range(n):
        for j in range(i + 2, n + 1):
            cost[i][j] = get_cost(s[i:j])

    # DP to find the minimum total changes to partition s into k semi-palindromes
    # dp[i][j] = min cost to partition s[0:j] into i semi-palindromes
    dp = [[float('inf')] * (n + 1) for _ in range(k + 1)]
    dp[0][0] = 0

    for i in range(1, k + 1):
        # A semi-palindrome must have at least length 2, so j must be at least 2*i
        for j in range(2 * i, n + 1):
            # Try all possible split points p
            # The last substring is s[p:j], and it must have length >= 2
            for p in range(2 * (i - 1), j - 1):
                if dp[i-1][p] != float('inf') and cost[p][j] != float('inf'):
                    dp[i][j] = min(dp[i][j], dp[i-1][p] + cost[p][j])

    return dp[k][n]
```

