```python
def longestCommonSufix(wordsContainer, wordsQuery):
    # A Trie will store the reversed words to handle suffixes as prefixes.
    # Each node will store the index of the "best" word passing through it.
    # "Best" is defined by: shortest length, then earliest index.
    trie = {}

    for idx, word in enumerate(wordsContainer):
        # Reverse the word to treat suffix as prefix
        rev_word = word[::-1]
        node = trie
        # For each prefix of the reversed word (which is a suffix of original)
        for char in rev_word:
            if char not in node:
                node[char] = {'best_idx': idx}
            else:
                # Update best_idx if current word is shorter or same length but smaller index
                current_best = node[char]['best_idx']
                if len(word) < len(wordsContainer[current_best]):
                    node[char]['best_idx'] = idx
                # (index is already handled by the order of iteration)
            node = node[char]

    # Find the global best word for the case where no common suffix exists (suffix = "")
    global_best_idx = 0
    for i in range(1, len(wordsContainer)):
        if len(wordsContainer[i]) < len(wordsContainer[global_best_idx]):
            global_best_idx = i

    ans = []
    for query in wordsQuery:
        rev_query = query[::-1]
        node = trie
        best_found_idx = global_best_idx

        for char in rev_query:
            if char in node:
                best_found_idx = node[char]['best_idx']
                node = node[char]
            else:
                # No longer common suffix possible
                break
        ans.append(best_found_idx)

    return ans
