def max_function_value(receiver, k):
    n = len(receiver)
    # Precompute binary lifting table
    LOG = 35  # Since k up to 1e10 needs ~35 bits
    next_node = [[-1] * n for _ in range(LOG)]
    sum_val = [[0] * n for _ in range(LOG)]

    # Base case (2^0 = 1 step)
    for i in range(n):
        next_node[0][i] = receiver[i]
        sum_val[0][i] = receiver[i]

    # Fill table
    for i in range(1, LOG):
        for j in range(n):
            mid = next_node[i-1][j]
            next_node[i][j] = next_node[i-1][mid] if mid != -1 else -1
            if mid != -1 and next_node[i][j] != -1:
                sum_val[i][j] = sum_val[i-1][j] + sum_val[i-1][mid]

    # Calculate f(x) for each starting point x
    def calc_f(x):
        total = x
        cur = x
        for i in range(LOG):
            if (k >> i) & 1:
                total += sum_val[i][cur]
                cur = next_node[i][cur]
        return total

    return max(calc_f(x) for x in range(n))
