```python
import math
from functools import reduce
from itertools import combinations

def kthSmallestAmount(coins, k):
    def count_upto(x):
        # Count numbers <= x that are multiples of at least one coin
        total = 0
        n = len(coins)
        for r in range(1, n+1):
            for combo in combinations(coins, r):
                lcm = reduce(lambda a, b: a * b // math.gcd(a, b), combo)
                if r % 2 == 1:
                    total += x // lcm
                else:
                    total -= x // lcm
        return total

    low, high = 1, max(coins) * k
    while low < high:
        mid = (low + high) // 2
        if count_upto(mid) >= k:
            high = mid
        else:
            low = mid + 1
    return low
```

