def min_operations_to_make_median_k(nums, k):
    nums.sort()
    n = len(nums)
    median_index = n // 2  # the larger of two middle elements when n is even
    operations = 0

    # The median value after sorting is at median_index
    if nums[median_index] == k:
        return 0

    # If median is less than k, we need to increase elements from median_index onward to at least k
    if nums[median_index] < k:
        for i in range(median_index, n):
            if nums[i] < k:
                operations += k - nums[i]
            else:
                break
    # If median is greater than k, we need to decrease elements from 0 to median_index to at most k
    else:
        for i in range(median_index, -1, -1):
            if nums[i] > k:
                operations += nums[i] - k
            else:
                break

    return operations
