import sys
from collections import deque

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    H = int(next(it))
    W = int(next(it))
    T = int(next(it))
    grid = []
    for _ in range(H):
        grid.append(next(it).strip())

    # locate important squares
    start = goal = None
    candies = []
    for i in range(H):
        row = grid[i]
        for j, ch in enumerate(row):
            if ch == 'S':
                start = (i, j)
            elif ch == 'G':
                goal = (i, j)
            elif ch == 'o':
                candies.append((i, j))

    K = len(candies)
    # nodes: 0 = start, 1 = goal, 2..K+1 = candies
    nodes = [start, goal] + candies
    N = K + 2

    INF = 10**9
    dist = [[INF] * N for _ in range(N)]

    # BFS from each node
    dirs = [(1,0), (-1,0), (0,1), (0,-1)]
    for idx, (si, sj) in enumerate(nodes):
        # BFS
        visited = [[-1] * W for _ in range(H)]
        dq = deque()
        visited[si][sj] = 0
        dq.append((si, sj))
        while dq:
            i, j = dq.popleft()
            d = visited[i][j]
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#':
                    if visited[ni][nj] == -1:
                        visited[ni][nj] = d + 1
                        dq.append((ni, nj))
        # record distances to other nodes
        for jdx, (ti, tj) in enumerate(nodes):
            if jdx == idx:
                continue
            d = visited[ti][tj]
            if d != -1:
                dist[idx][jdx] = d

    # handle no candies case
    if K == 0:
        if dist[0][1] <= T:
            print(0)
        else:
            print(-1)
        return

    # DP over subsets of candies
    # dp[mask][c] = min distance to end at candy c (0-indexed among candies) after visiting mask
    dp = [[INF] * K for _ in range(1 << K)]
    # initialize from start to each candy
    for c in range(K):
        d = dist[0][2 + c]  # node index of candy c is 2+c
        if d < INF:
            dp[1 << c][c] = d

    # iterate over all masks
    for mask in range(1 << K):
        for last in range(K):
            cur = dp[mask][last]
            if cur == INF:
                continue
            # try to go to another candy
            for nxt in range(K):
                if mask & (1 << nxt):
                    continue
                new_mask = mask | (1 << nxt)
                nd = cur + dist[2 + last][2 + nxt]
                if nd < dp[new_mask][nxt]:
                    dp[new_mask][nxt] = nd

    # find best answer
    best = -1
    # direct start -> goal
    if dist[0][1] <= T:
        best = 0
    # try all masks
    for mask in range(1 << K):
        cnt = bin(mask).count('1')
        if cnt <= best:
            continue
        for last in range(K):
            d = dp[mask][last]
            if d == INF:
                continue
            total = d + dist[2 + last][1]  # to goal
            if total <= T:
                best = cnt
                break  # no need to check other last for this mask

    print(best)

if __name__ == "__main__":
    solve()
