def max_complete_subset_sum(nums):
    n = len(nums)
    # For each index i (1-based), compute its square-free part
    def square_free(x):
        d = 2
        res = 1
        while d * d <= x:
            cnt = 0
            while x % d == 0:
                x //= d
                cnt += 1
            if cnt % 2 == 1:
                res *= d
            d += 1
        if x > 1:
            res *= x
        return res

    # Group indices by their square-free part
    groups = {}
    for i in range(1, n + 1):
        sf = square_free(i)
        if sf not in groups:
            groups[sf] = []
        groups[sf].append(nums[i - 1])

    # For each group, sum all elements (since any two indices in same group have product a square)
    max_sum = 0
    for group in groups.values():
        max_sum = max(max_sum, sum(group))

    return max_sum
