def punishmentNumber(n):
    def canPartition(num_str, target, current_sum, index):
        if index == len(num_str):
            return current_sum == target

        for i in range(index + 1, len(num_str) + 1):
            substring = num_str[index:i]
            # Avoid numbers with leading zeros (except "0" itself)
            if len(substring) > 1 and substring[0] == '0':
                continue

            value = int(substring)
            if canPartition(num_str, target, current_sum + value, i):
                return True

        return False

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)

        if canPartition(square_str, i, 0, 0):
            total += square

    return total
