def countCompleteSubstrings(word, k):
    def count_substrings(s, k):
        n = len(s)
        if n < k:
            return 0

        result = 0

        # Iterate over possible substring lengths: k, 2k, 3k, ..., 26k (at most 26 unique chars)
        for num_chars in range(1, 27):
            length = num_chars * k
            if length > n:
                break

            # Use sliding window of size 'length'
            char_count = {}

            # Initialize first window
            for i in range(length):
                char_count[s[i]] = char_count.get(s[i], 0) + 1

            # Check if current window is valid
            if is_valid_substring(char_count, k):
                result += 1

            # Slide the window
            for i in range(length, n):
                # Add new character
                char_count[s[i]] = char_count.get(s[i], 0) + 1
                # Remove old character
                char_count[s[i - length]] -= 1
                if char_count[s[i - length]] == 0:
                    del char_count[s[i - length]]

                # Check if current window is valid
                if is_valid_substring(char_count, k):
                    result += 1

        return result

    def is_valid_substring(char_count, k):
        # Check if each character appears exactly k times
        for count in char_count.values():
            if count != k:
                return False
        return True

    def is_adjacent_valid(s):
        # Check if difference between adjacent characters is at most 2
        for i in range(len(s) - 1):
            if abs(ord(s[i]) - ord(s[i + 1])) > 2:
                return False
        return True

    result = 0
    n = len(word)

    # Split the string at positions where adjacent characters differ by more than 2
    start = 0
    for i in range(1, n):
        if abs(ord(word[i]) - ord(word[i-1])) > 2:
            # Process the segment from start to i
            segment = word[start:i]
            result += count_substrings(segment, k)
            start = i

    # Process the last segment
    segment = word[start:]
    result += count_substrings(segment, k)

    return result
