    for i in range(n):
        a = int(data[idx]); b = int(data[idx+1]); idx += 2
        tiles.append((a, b))

    # Check total area first
    grid_area = h * w
    # Try all subsets and arrangements
    def can_cover():
        # Try all subsets of tiles (using bit masks)
        for mask in range(1, 1 << n):
            area = 0
            used_tiles = []
            for i in range(n):
                if mask & (1 << i):
                    a, b = tiles[i]
                    # Consider both orientations
                    area += a * b
                    used_tiles.append(tiles[i])

            if area != grid_area:
                continue

            # Try all permutations of used tiles
            for perm in set(permutations(used_tiles)):
                # Try to pack into h x w grid using simple backtracking
                grid = [[False] * w for _ in range(h)]

                def place_tile(tile_idx, row=0, col=0):
                    if tile_idx == len(perm):
                        return True

                    a, b = perm[tile_idx]
                    # Try both orientations
                    orientations = [(a, b), (b, a)]

                    for orient_a, orient_b in orientations:
                        # Find first empty cell
                        start_r, start_c = -1, -1
                        found = False
                        for r in range(h):
                            if found: break
                            for c in range(w):
                                if not grid[r][c]:
                                    start_r, start_c = r, c
                                    found = True
                                    break

                        if start_r == -1:
                            return True  # Grid full but not all tiles placed? Shouldn't happen if area matches

                        # Check if tile fits starting at (start_r, start_c)
                        can_place = True
                        for dr in range(orient_a):
                            for dc in range(orient_b):
                                nr, nc = start_r + dr, start_c + dc
                                if nr >= h or nc >= w or grid[nr][nc]:
                                    can_place = False
                                    break
                            if not can_place: break

                        if can_place:
                            # Place tile
                            for dr in range(orient_a):
                                for dc in range(orient_b):
                                    grid[start_r + dr][start_c + dc] = True

                            if place_tile(tile_idx + 1):
                                return True

                            # Undo placement
                            for dr in range(orient_a):
                                for dc in range(orient_b):
                                    grid[start_r + dr][start_c + dc] = False

                    return False

                if place_tile(0):
                    return True

        return False

    if can_cover():
