from collections import deque

def min_operations(x, y):
    if x == y:
        return 0

    visited = set()
    queue = deque([(x, 0)])
    visited.add(x)

    while queue:
        curr, ops = queue.popleft()

        # Generate next states
        next_states = []
        if curr % 11 == 0:
            next_states.append(curr // 11)
        if curr % 5 == 0:
            next_states.append(curr // 5)
        next_states.append(curr - 1)
        next_states.append(curr + 1)

        for nxt in next_states:
            if nxt == y:
                return ops + 1
            if 0 <= nxt <= 20000 and nxt not in visited:
                visited.add(nxt)
                queue.append((nxt, ops + 1))

    return -1
