def can_split_array(nums, m):
    n = len(nums)
    if n <= 1:
        return True

    # Precompute prefix sums
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]

    def get_sum(i, j):
        return prefix[j + 1] - prefix[i]

    # Check all possible splits recursively with memoization
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(i, j):
        if i == j:
            return True

        total = get_sum(i, j)

        # Try all possible split positions
        for k in range(i, j):
            left_sum = get_sum(i, k)
            right_sum = get_sum(k + 1, j)

            left_valid = (k - i + 1 == 1) or left_sum >= m
            right_valid = (j - k == 1) or right_sum >= m

            if left_valid and right_valid:
                if dfs(i, k) and dfs(k + 1, j):
                    return True

        return False

    return dfs(0, n - 1)
