from typing import List

def can_traverse_all_pairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1

    # For each number, factorize and connect indices sharing prime factors
    prime_to_indices = {}

    for i, num in enumerate(nums):
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                if d not in prime_to_indices:
                    prime_to_indices[d] = []
                prime_to_indices[d].append(i)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:
            if temp not in prime_to_indices:
                prime_to_indices[temp] = []
            prime_to_indices[temp].append(i)

    # Union all indices sharing the same prime factor
    for primes in prime_to_indices.values():
        for i in range(1, len(primes)):
            union(primes[0], primes[i])

    # Check if all indices belong to the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
