def specialPerm(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute divisibility graph
    valid = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i != j:
                valid[i][j] = (nums[i] % nums[j] == 0) or (nums[j] % nums[i] == 0)

    from functools import lru_cache

    @lru_cache(None)
    def dp(last, mask):
        if mask == (1 << n) - 1:
            return 1

        count = 0
        for i in range(n):
            if not (mask & (1 << i)) and (last == -1 or valid[last][i]):
                count = (count + dp(i, mask | (1 << i))) % MOD
        return count

